export const LANGUAGES=[
  ["auto","🌐 Auto"],
  ["fr","🇫🇷 Français"],["en-GB","🇬🇧 English"],["en-US","🇺🇸 English (US)"],["es","🇪🇸 Español"],["it","🇮🇹 Italiano"],["de","🇩🇪 Deutsch"],["pt","🇵🇹 Português"],["nl","🇳🇱 Nederlands"],["zh","🇨🇳 中文"],["ja","🇯🇵 日本語"],["ru","🇷🇺 Русский"],["ar","🇸🇦 العربية"],["pl","🇵🇱 Polski"],["tr","🇹🇷 Türkçe"],["ko","🇰🇷 한국어"],["vi","🇻🇳 Tiếng Việt"],["th","🇹🇭 ไทย"],["id","🇮🇩 Bahasa Indonesia"],["uk","🇺🇦 Українська"],["ro","🇷🇴 Română"],["el","🇬🇷 Ελληνικά"],["cs","🇨🇿 Čeština"],["sv","🇸🇪 Svenska"]
];
function detected(){
  const list=navigator.languages?.length?navigator.languages:[navigator.language||"en"];
  for(const raw of list){
    const l=String(raw).toLowerCase();
    if(l.startsWith("fr"))return"fr";if(l==="en-us"||l.startsWith("en-us"))return"en-US";if(l.startsWith("en"))return"en-GB";
    if(l.startsWith("es"))return"es";if(l.startsWith("it"))return"it";if(l.startsWith("de"))return"de";if(l.startsWith("pt"))return"pt";if(l.startsWith("nl"))return"nl";
    if(l.startsWith("zh"))return"zh";if(l.startsWith("ja"))return"ja";if(l.startsWith("ru"))return"ru";if(l.startsWith("ar"))return"ar";if(l.startsWith("pl"))return"pl";if(l.startsWith("tr"))return"tr";if(l.startsWith("ko"))return"ko";if(l.startsWith("vi"))return"vi";if(l.startsWith("th"))return"th";if(l.startsWith("id"))return"id";if(l.startsWith("uk"))return"uk";if(l.startsWith("ro"))return"ro";if(l.startsWith("el"))return"el";if(l.startsWith("cs"))return"cs";if(l.startsWith("sv"))return"sv";
  }
  return"en-GB"
}
export function resolveLanguage(choice){return !choice||choice==="auto"?detected():(packs[choice]?choice:"en-GB")}
export function localeFor(lang){return ({fr:"fr-FR","en-GB":"en-GB","en-US":"en-US",es:"es-ES",it:"it-IT",de:"de-DE",pt:"pt-PT",nl:"nl-NL",zh:"zh-CN",ja:"ja-JP",ru:"ru-RU",ar:"ar-SA",pl:"pl-PL",tr:"tr-TR",ko:"ko-KR",vi:"vi-VN",th:"th-TH",id:"id-ID",uk:"uk-UA",ro:"ro-RO",el:"el-GR",cs:"cs-CZ",sv:"sv-SE"})[lang]||"en-GB"}
export function dirFor(lang){return lang==="ar"?"rtl":"ltr"}
export function translator(lang){const pack=packs[lang]||EN;return (key,vars={})=>{let text=pack[key]??EN[key]??key;for(const [k,v] of Object.entries(vars))text=text.replaceAll(`{${k}}`,String(v));return text}}

