// ===== V2.5.14 · Cloud Auth Reliability =====
const AUTH514_LABELS={
  en:["WarBoost cannot read the cloud configuration right now. Check your connection and try again.","WarBoost authentication could not start on this device. Reload the app and try again.","WarBoost Cloud is configured, but authentication is temporarily unreachable. Check your connection and try again."],
  fr:["WarBoost ne peut pas lire la configuration cloud pour le moment. Vérifie ta connexion puis réessaie.","L’authentification WarBoost n’a pas pu démarrer sur cet appareil. Recharge l’application puis réessaie.","Le Cloud WarBoost est configuré, mais l’authentification est temporairement inaccessible. Vérifie ta connexion puis réessaie."],
  es:["WarBoost no puede leer la configuración de la nube ahora. Comprueba tu conexión e inténtalo de nuevo.","La autenticación de WarBoost no pudo iniciarse en este dispositivo. Recarga la aplicación e inténtalo de nuevo.","WarBoost Cloud está configurado, pero la autenticación no está disponible temporalmente. Comprueba tu conexión e inténtalo de nuevo."],
  it:["WarBoost non riesce a leggere la configurazione cloud al momento. Controlla la connessione e riprova.","L’autenticazione WarBoost non è riuscita ad avviarsi su questo dispositivo. Ricarica l’app e riprova.","WarBoost Cloud è configurato, ma l’autenticazione è temporaneamente irraggiungibile. Controlla la connessione e riprova."],
  de:["WarBoost kann die Cloud-Konfiguration momentan nicht laden. Prüfe die Verbindung und versuche es erneut.","Die WarBoost-Authentifizierung konnte auf diesem Gerät nicht gestartet werden. Lade die App neu und versuche es erneut.","WarBoost Cloud ist konfiguriert, aber die Anmeldung ist vorübergehend nicht erreichbar. Prüfe die Verbindung und versuche es erneut."],
  pt:["O WarBoost não consegue ler a configuração cloud neste momento. Verifica a ligação e tenta novamente.","A autenticação WarBoost não conseguiu iniciar neste dispositivo. Recarrega a aplicação e tenta novamente.","O WarBoost Cloud está configurado, mas a autenticação está temporariamente indisponível. Verifica a ligação e tenta novamente."],
  nl:["WarBoost kan de cloudconfiguratie momenteel niet lezen. Controleer je verbinding en probeer opnieuw.","WarBoost-authenticatie kon op dit apparaat niet starten. Herlaad de app en probeer opnieuw.","WarBoost Cloud is geconfigureerd, maar authenticatie is tijdelijk onbereikbaar. Controleer je verbinding en probeer opnieuw."],
  zh:["WarBoost 目前无法读取云端配置。请检查网络后重试。","WarBoost 身份验证无法在此设备上启动。请重新加载应用后重试。","WarBoost Cloud 已配置，但身份验证暂时无法连接。请检查网络后重试。"],
  ja:["現在 WarBoost はクラウド設定を読み込めません。接続を確認して再試行してください。","この端末で WarBoost 認証を開始できませんでした。アプリを再読み込みして再試行してください。","WarBoost Cloud は設定済みですが、認証に一時的に接続できません。接続を確認して再試行してください。"],
  ru:["WarBoost сейчас не может прочитать облачную конфигурацию. Проверьте соединение и повторите попытку.","Не удалось запустить аутентификацию WarBoost на этом устройстве. Перезагрузите приложение и повторите попытку.","WarBoost Cloud настроен, но аутентификация временно недоступна. Проверьте соединение и повторите попытку."],
  ar:["يتعذر على WarBoost قراءة إعدادات السحابة الآن. تحقق من الاتصال ثم أعد المحاولة.","تعذر بدء مصادقة WarBoost على هذا الجهاز. أعد تحميل التطبيق ثم حاول مرة أخرى.","تم إعداد WarBoost Cloud، لكن المصادقة غير متاحة مؤقتًا. تحقق من الاتصال ثم أعد المحاولة."],
  pl:["WarBoost nie może teraz odczytać konfiguracji chmury. Sprawdź połączenie i spróbuj ponownie.","Nie udało się uruchomić uwierzytelniania WarBoost na tym urządzeniu. Przeładuj aplikację i spróbuj ponownie.","WarBoost Cloud jest skonfigurowany, ale uwierzytelnianie jest chwilowo niedostępne. Sprawdź połączenie i spróbuj ponownie."],
  tr:["WarBoost şu anda bulut yapılandırmasını okuyamıyor. Bağlantını kontrol edip yeniden dene.","WarBoost kimlik doğrulaması bu cihazda başlatılamadı. Uygulamayı yeniden yükleyip tekrar dene.","WarBoost Cloud yapılandırılmış, ancak kimlik doğrulama geçici olarak ulaşılamıyor. Bağlantını kontrol edip yeniden dene."],
  ko:["현재 WarBoost가 클라우드 설정을 읽을 수 없습니다. 연결을 확인한 뒤 다시 시도하세요.","이 기기에서 WarBoost 인증을 시작하지 못했습니다. 앱을 새로고침한 뒤 다시 시도하세요.","WarBoost Cloud는 구성되어 있지만 인증에 일시적으로 연결할 수 없습니다. 연결을 확인한 뒤 다시 시도하세요."],
  vi:["WarBoost hiện không thể đọc cấu hình đám mây. Hãy kiểm tra kết nối rồi thử lại.","Xác thực WarBoost không thể khởi động trên thiết bị này. Hãy tải lại ứng dụng rồi thử lại.","WarBoost Cloud đã được cấu hình nhưng xác thực tạm thời không truy cập được. Hãy kiểm tra kết nối rồi thử lại."],
  th:["ขณะนี้ WarBoost อ่านการตั้งค่าคลาวด์ไม่ได้ โปรดตรวจสอบการเชื่อมต่อแล้วลองอีกครั้ง","ไม่สามารถเริ่มการยืนยันตัวตน WarBoost บนอุปกรณ์นี้ได้ โปรดโหลดแอปใหม่แล้วลองอีกครั้ง","WarBoost Cloud ตั้งค่าแล้ว แต่ระบบยืนยันตัวตนเข้าถึงไม่ได้ชั่วคราว โปรดตรวจสอบการเชื่อมต่อแล้วลองอีกครั้ง"],
  id:["WarBoost saat ini tidak dapat membaca konfigurasi cloud. Periksa koneksi lalu coba lagi.","Autentikasi WarBoost tidak dapat dimulai di perangkat ini. Muat ulang aplikasi lalu coba lagi.","WarBoost Cloud sudah dikonfigurasi, tetapi autentikasi sementara tidak dapat dijangkau. Periksa koneksi lalu coba lagi."],
  uk:["WarBoost зараз не може прочитати конфігурацію хмари. Перевір з’єднання та спробуй ще раз.","Не вдалося запустити автентифікацію WarBoost на цьому пристрої. Перезавантаж застосунок і спробуй ще раз.","WarBoost Cloud налаштований, але автентифікація тимчасово недоступна. Перевір з’єднання та спробуй ще раз."],
  ro:["WarBoost nu poate citi momentan configurația cloud. Verifică conexiunea și încearcă din nou.","Autentificarea WarBoost nu a putut porni pe acest dispozitiv. Reîncarcă aplicația și încearcă din nou.","WarBoost Cloud este configurat, dar autentificarea este temporar inaccesibilă. Verifică conexiunea și încearcă din nou."],
  el:["Το WarBoost δεν μπορεί τώρα να διαβάσει τη ρύθμιση cloud. Έλεγξε τη σύνδεση και δοκίμασε ξανά.","Η ταυτοποίηση WarBoost δεν μπόρεσε να ξεκινήσει σε αυτή τη συσκευή. Φόρτωσε ξανά την εφαρμογή και δοκίμασε ξανά.","Το WarBoost Cloud είναι ρυθμισμένο, αλλά η ταυτοποίηση είναι προσωρινά μη διαθέσιμη. Έλεγξε τη σύνδεση και δοκίμασε ξανά."],
  cs:["WarBoost teď nemůže načíst konfiguraci cloudu. Zkontroluj připojení a zkus to znovu.","Ověření WarBoost se na tomto zařízení nepodařilo spustit. Načti aplikaci znovu a zkus to znovu.","WarBoost Cloud je nakonfigurován, ale ověření je dočasně nedostupné. Zkontroluj připojení a zkus to znovu."],
  sv:["WarBoost kan inte läsa molnkonfigurationen just nu. Kontrollera anslutningen och försök igen.","WarBoost-autentisering kunde inte starta på den här enheten. Ladda om appen och försök igen.","WarBoost Cloud är konfigurerat, men autentisering kan tillfälligt inte nås. Kontrollera anslutningen och försök igen."]
};
for(const [code,labels] of Object.entries(AUTH514_LABELS)){
  const targets=code==="en"?[EN,EN_GB,EN_US]:[packs[code]].filter(Boolean);
  targets.forEach(target=>Object.assign(target,{auth_cloud_config_unreachable:labels[0],auth_client_unavailable:labels[1],auth_cloud_unreachable:labels[2]}));
}


