// ===== V2.5.25 · Secure password recovery =====
const V2525_AUTH_LABELS={
  en:["Forgot password?","Enter your WarBoost email address.","If an account exists for this email, a reset link has been sent.","Account recovery","Choose a new password","The email link opens a temporary recovery session. Your new password is sent only to Supabase Auth.","Checking the recovery link…","New password","Confirm new password","Use at least 8 characters.","Save new password","Back to WarBoost","This recovery link has expired. Request a new one from WarBoost.","This password does not meet the security requirements.","This recovery link is invalid or has already been used.","Use at least 8 characters.","The two passwords do not match.","Saving…","Password updated. You can now sign in with the new password."],
  fr:["Mot de passe oublié ?","Entre ton adresse e-mail WarBoost.","Si un compte existe pour cet e-mail, un lien de réinitialisation a été envoyé.","Récupération du compte","Choisis un nouveau mot de passe","Le lien reçu par e-mail ouvre une session de récupération temporaire. Ton nouveau mot de passe est envoyé uniquement à Supabase Auth.","Vérification du lien de récupération…","Nouveau mot de passe","Confirme le nouveau mot de passe","Utilise au moins 8 caractères.","Enregistrer le nouveau mot de passe","Retour à WarBoost","Ce lien de récupération a expiré. Demande un nouveau lien depuis WarBoost.","Ce mot de passe ne respecte pas les exigences de sécurité.","Ce lien de récupération est invalide ou a déjà été utilisé.","Utilise au moins 8 caractères.","Les deux mots de passe ne correspondent pas.","Enregistrement…","Mot de passe mis à jour. Tu peux maintenant te connecter avec le nouveau mot de passe."],
  es:["¿Olvidaste la contraseña?","Introduce tu correo de WarBoost.","Si existe una cuenta para este correo, se ha enviado un enlace de restablecimiento.","Recuperación de cuenta","Elige una nueva contraseña","El enlace del correo abre una sesión temporal de recuperación. Tu nueva contraseña se envía únicamente a Supabase Auth.","Comprobando el enlace de recuperación…","Nueva contraseña","Confirmar nueva contraseña","Usa al menos 8 caracteres.","Guardar nueva contraseña","Volver a WarBoost","Este enlace ha caducado. Solicita uno nuevo desde WarBoost.","La contraseña no cumple los requisitos de seguridad.","Este enlace no es válido o ya fue utilizado.","Usa al menos 8 caracteres.","Las contraseñas no coinciden.","Guardando…","Contraseña actualizada. Ya puedes iniciar sesión con la nueva contraseña."],
  it:["Password dimenticata?","Inserisci la tua e-mail WarBoost.","Se esiste un account per questa e-mail, è stato inviato un link di reimpostazione.","Recupero account","Scegli una nuova password","Il link e-mail apre una sessione di recupero temporanea. La nuova password viene inviata solo a Supabase Auth.","Verifica del link di recupero…","Nuova password","Conferma nuova password","Usa almeno 8 caratteri.","Salva nuova password","Torna a WarBoost","Questo link è scaduto. Richiedine uno nuovo da WarBoost.","La password non rispetta i requisiti di sicurezza.","Questo link non è valido o è già stato usato.","Usa almeno 8 caratteri.","Le password non coincidono.","Salvataggio…","Password aggiornata. Ora puoi accedere con la nuova password."],
  de:["Passwort vergessen?","Gib deine WarBoost-E-Mail-Adresse ein.","Wenn für diese E-Mail ein Konto existiert, wurde ein Link zum Zurücksetzen gesendet.","Kontowiederherstellung","Neues Passwort wählen","Der E-Mail-Link öffnet eine temporäre Wiederherstellungssitzung. Dein neues Passwort wird nur an Supabase Auth gesendet.","Wiederherstellungslink wird geprüft…","Neues Passwort","Neues Passwort bestätigen","Mindestens 8 Zeichen verwenden.","Neues Passwort speichern","Zurück zu WarBoost","Dieser Link ist abgelaufen. Fordere in WarBoost einen neuen an.","Das Passwort erfüllt die Sicherheitsanforderungen nicht.","Dieser Link ist ungültig oder wurde bereits verwendet.","Mindestens 8 Zeichen verwenden.","Die Passwörter stimmen nicht überein.","Speichern…","Passwort aktualisiert. Du kannst dich jetzt mit dem neuen Passwort anmelden."],
  pt:["Esqueceste a palavra-passe?","Introduz o teu e-mail WarBoost.","Se existir uma conta para este e-mail, foi enviado um link de reposição.","Recuperação de conta","Escolhe uma nova palavra-passe","O link do e-mail abre uma sessão temporária de recuperação. A nova palavra-passe é enviada apenas ao Supabase Auth.","A verificar o link de recuperação…","Nova palavra-passe","Confirmar nova palavra-passe","Usa pelo menos 8 caracteres.","Guardar nova palavra-passe","Voltar ao WarBoost","Este link expirou. Pede um novo no WarBoost.","A palavra-passe não cumpre os requisitos de segurança.","Este link é inválido ou já foi utilizado.","Usa pelo menos 8 caracteres.","As palavras-passe não coincidem.","A guardar…","Palavra-passe atualizada. Já podes iniciar sessão com a nova palavra-passe."],
  nl:["Wachtwoord vergeten?","Voer je WarBoost-e-mailadres in.","Als er een account voor dit e-mailadres bestaat, is er een resetlink verzonden.","Accountherstel","Kies een nieuw wachtwoord","De e-maillink opent een tijdelijke herstelsessie. Je nieuwe wachtwoord wordt alleen naar Supabase Auth gestuurd.","Herstellink controleren…","Nieuw wachtwoord","Nieuw wachtwoord bevestigen","Gebruik minimaal 8 tekens.","Nieuw wachtwoord opslaan","Terug naar WarBoost","Deze link is verlopen. Vraag een nieuwe aan in WarBoost.","Dit wachtwoord voldoet niet aan de beveiligingseisen.","Deze link is ongeldig of al gebruikt.","Gebruik minimaal 8 tekens.","De wachtwoorden komen niet overeen.","Opslaan…","Wachtwoord bijgewerkt. Je kunt nu inloggen met het nieuwe wachtwoord."],
  zh:["忘记密码？","输入你的 WarBoost 邮箱地址。","如果该邮箱存在账户，重置链接已发送。","账户恢复","设置新密码","邮件链接会打开临时恢复会话。新密码只会发送给 Supabase Auth。","正在检查恢复链接…","新密码","确认新密码","至少使用 8 个字符。","保存新密码","返回 WarBoost","此恢复链接已过期。请在 WarBoost 中申请新链接。","此密码不符合安全要求。","此恢复链接无效或已被使用。","至少使用 8 个字符。","两次输入的密码不一致。","正在保存…","密码已更新。现在可以使用新密码登录。"],
  ja:["パスワードを忘れた場合","WarBoostのメールアドレスを入力してください。","このメールにアカウントが存在する場合、リセットリンクが送信されました。","アカウント復旧","新しいパスワードを設定","メールのリンクで一時的な復旧セッションを開きます。新しいパスワードはSupabase Authにのみ送信されます。","復旧リンクを確認中…","新しいパスワード","新しいパスワードを確認","8文字以上を使用してください。","新しいパスワードを保存","WarBoostに戻る","この復旧リンクは期限切れです。WarBoostから新しいリンクを申請してください。","このパスワードはセキュリティ要件を満たしていません。","この復旧リンクは無効か、すでに使用されています。","8文字以上を使用してください。","パスワードが一致しません。","保存中…","パスワードを更新しました。新しいパスワードでログインできます。"],
  ru:["Забыли пароль?","Введите e-mail WarBoost.","Если аккаунт с таким e-mail существует, ссылка для сброса отправлена.","Восстановление аккаунта","Выберите новый пароль","Ссылка из письма открывает временную сессию восстановления. Новый пароль отправляется только в Supabase Auth.","Проверка ссылки восстановления…","Новый пароль","Подтвердите новый пароль","Используйте не менее 8 символов.","Сохранить новый пароль","Вернуться в WarBoost","Срок действия ссылки истёк. Запросите новую в WarBoost.","Пароль не соответствует требованиям безопасности.","Ссылка недействительна или уже использована.","Используйте не менее 8 символов.","Пароли не совпадают.","Сохранение…","Пароль обновлён. Теперь можно войти с новым паролем."],
  ar:["هل نسيت كلمة المرور؟","أدخل بريد WarBoost الإلكتروني.","إذا كان هناك حساب لهذا البريد فقد تم إرسال رابط إعادة التعيين.","استعادة الحساب","اختر كلمة مرور جديدة","يفتح رابط البريد جلسة استعادة مؤقتة. يتم إرسال كلمة المرور الجديدة فقط إلى Supabase Auth.","جارٍ التحقق من رابط الاستعادة…","كلمة مرور جديدة","تأكيد كلمة المرور الجديدة","استخدم 8 أحرف على الأقل.","حفظ كلمة المرور الجديدة","العودة إلى WarBoost","انتهت صلاحية رابط الاستعادة. اطلب رابطاً جديداً من WarBoost.","كلمة المرور لا تستوفي متطلبات الأمان.","رابط الاستعادة غير صالح أو تم استخدامه بالفعل.","استخدم 8 أحرف على الأقل.","كلمتا المرور غير متطابقتين.","جارٍ الحفظ…","تم تحديث كلمة المرور. يمكنك الآن تسجيل الدخول بكلمة المرور الجديدة."],
  pl:["Nie pamiętasz hasła?","Wpisz adres e-mail WarBoost.","Jeśli konto dla tego adresu istnieje, wysłano link do resetowania.","Odzyskiwanie konta","Ustaw nowe hasło","Link z wiadomości otwiera tymczasową sesję odzyskiwania. Nowe hasło jest wysyłane wyłącznie do Supabase Auth.","Sprawdzanie linku odzyskiwania…","Nowe hasło","Potwierdź nowe hasło","Użyj co najmniej 8 znaków.","Zapisz nowe hasło","Wróć do WarBoost","Link wygasł. Poproś o nowy w WarBoost.","Hasło nie spełnia wymagań bezpieczeństwa.","Link jest nieprawidłowy lub został już użyty.","Użyj co najmniej 8 znaków.","Hasła nie są takie same.","Zapisywanie…","Hasło zaktualizowane. Możesz zalogować się nowym hasłem."],
  tr:["Şifreni mi unuttun?","WarBoost e-posta adresini gir.","Bu e-postaya ait bir hesap varsa sıfırlama bağlantısı gönderildi.","Hesap kurtarma","Yeni bir şifre seç","E-posta bağlantısı geçici bir kurtarma oturumu açar. Yeni şifren yalnızca Supabase Auth'a gönderilir.","Kurtarma bağlantısı kontrol ediliyor…","Yeni şifre","Yeni şifreyi doğrula","En az 8 karakter kullan.","Yeni şifreyi kaydet","WarBoost'a dön","Bu bağlantının süresi doldu. WarBoost'tan yeni bir bağlantı iste.","Bu şifre güvenlik gereksinimlerini karşılamıyor.","Bu bağlantı geçersiz veya daha önce kullanılmış.","En az 8 karakter kullan.","Şifreler eşleşmiyor.","Kaydediliyor…","Şifre güncellendi. Artık yeni şifreyle giriş yapabilirsin."],
  ko:["비밀번호를 잊으셨나요?","WarBoost 이메일 주소를 입력하세요.","이 이메일의 계정이 존재하면 재설정 링크를 보냈습니다.","계정 복구","새 비밀번호 설정","이메일 링크는 임시 복구 세션을 엽니다. 새 비밀번호는 Supabase Auth에만 전송됩니다.","복구 링크 확인 중…","새 비밀번호","새 비밀번호 확인","8자 이상 사용하세요.","새 비밀번호 저장","WarBoost로 돌아가기","복구 링크가 만료되었습니다. WarBoost에서 새 링크를 요청하세요.","비밀번호가 보안 요구사항을 충족하지 않습니다.","복구 링크가 잘못되었거나 이미 사용되었습니다.","8자 이상 사용하세요.","비밀번호가 일치하지 않습니다.","저장 중…","비밀번호가 업데이트되었습니다. 이제 새 비밀번호로 로그인할 수 있습니다."],
  vi:["Quên mật khẩu?","Nhập e-mail WarBoost của bạn.","Nếu có tài khoản với e-mail này, liên kết đặt lại đã được gửi.","Khôi phục tài khoản","Chọn mật khẩu mới","Liên kết trong e-mail mở một phiên khôi phục tạm thời. Mật khẩu mới chỉ được gửi đến Supabase Auth.","Đang kiểm tra liên kết khôi phục…","Mật khẩu mới","Xác nhận mật khẩu mới","Dùng ít nhất 8 ký tự.","Lưu mật khẩu mới","Quay lại WarBoost","Liên kết đã hết hạn. Hãy yêu cầu liên kết mới từ WarBoost.","Mật khẩu không đáp ứng yêu cầu bảo mật.","Liên kết không hợp lệ hoặc đã được sử dụng.","Dùng ít nhất 8 ký tự.","Hai mật khẩu không khớp.","Đang lưu…","Đã cập nhật mật khẩu. Bạn có thể đăng nhập bằng mật khẩu mới."],
  th:["ลืมรหัสผ่าน?","กรอกอีเมล WarBoost ของคุณ","หากมีบัญชีสำหรับอีเมลนี้ ระบบได้ส่งลิงก์รีเซ็ตแล้ว","กู้คืนบัญชี","ตั้งรหัสผ่านใหม่","ลิงก์ในอีเมลจะเปิดเซสชันกู้คืนชั่วคราว รหัสผ่านใหม่จะถูกส่งไปยัง Supabase Auth เท่านั้น","กำลังตรวจสอบลิงก์กู้คืน…","รหัสผ่านใหม่","ยืนยันรหัสผ่านใหม่","ใช้อย่างน้อย 8 ตัวอักษร","บันทึกรหัสผ่านใหม่","กลับไป WarBoost","ลิงก์กู้คืนหมดอายุแล้ว ขอใหม่จาก WarBoost","รหัสผ่านไม่ผ่านข้อกำหนดด้านความปลอดภัย","ลิงก์กู้คืนไม่ถูกต้องหรือถูกใช้ไปแล้ว","ใช้อย่างน้อย 8 ตัวอักษร","รหัสผ่านทั้งสองไม่ตรงกัน","กำลังบันทึก…","อัปเดตรหัสผ่านแล้ว ตอนนี้เข้าสู่ระบบด้วยรหัสผ่านใหม่ได้"],
  id:["Lupa kata sandi?","Masukkan email WarBoost kamu.","Jika akun untuk email ini ada, tautan reset telah dikirim.","Pemulihan akun","Pilih kata sandi baru","Tautan email membuka sesi pemulihan sementara. Kata sandi baru hanya dikirim ke Supabase Auth.","Memeriksa tautan pemulihan…","Kata sandi baru","Konfirmasi kata sandi baru","Gunakan minimal 8 karakter.","Simpan kata sandi baru","Kembali ke WarBoost","Tautan ini kedaluwarsa. Minta tautan baru dari WarBoost.","Kata sandi tidak memenuhi persyaratan keamanan.","Tautan ini tidak valid atau sudah digunakan.","Gunakan minimal 8 karakter.","Kata sandi tidak sama.","Menyimpan…","Kata sandi diperbarui. Kamu sekarang dapat masuk dengan kata sandi baru."],
  uk:["Забули пароль?","Введіть e-mail WarBoost.","Якщо акаунт із цим e-mail існує, посилання для скидання надіслано.","Відновлення акаунта","Оберіть новий пароль","Посилання з листа відкриває тимчасову сесію відновлення. Новий пароль надсилається лише до Supabase Auth.","Перевірка посилання відновлення…","Новий пароль","Підтвердьте новий пароль","Використовуйте щонайменше 8 символів.","Зберегти новий пароль","Повернутися до WarBoost","Термін дії посилання минув. Запросіть нове у WarBoost.","Пароль не відповідає вимогам безпеки.","Посилання недійсне або вже використане.","Використовуйте щонайменше 8 символів.","Паролі не збігаються.","Збереження…","Пароль оновлено. Тепер можна увійти з новим паролем."],
  ro:["Ai uitat parola?","Introdu e-mailul WarBoost.","Dacă există un cont pentru acest e-mail, a fost trimis un link de resetare.","Recuperare cont","Alege o parolă nouă","Linkul din e-mail deschide o sesiune temporară de recuperare. Noua parolă este trimisă doar către Supabase Auth.","Se verifică linkul de recuperare…","Parolă nouă","Confirmă parola nouă","Folosește cel puțin 8 caractere.","Salvează parola nouă","Înapoi la WarBoost","Linkul a expirat. Cere unul nou din WarBoost.","Parola nu îndeplinește cerințele de securitate.","Linkul este invalid sau a fost deja folosit.","Folosește cel puțin 8 caractere.","Parolele nu coincid.","Se salvează…","Parola a fost actualizată. Te poți conecta cu noua parolă."],
  el:["Ξέχασες τον κωδικό;","Εισήγαγε το e-mail WarBoost.","Αν υπάρχει λογαριασμός για αυτό το e-mail, στάλθηκε σύνδεσμος επαναφοράς.","Ανάκτηση λογαριασμού","Διάλεξε νέο κωδικό","Ο σύνδεσμος του e-mail ανοίγει προσωρινή συνεδρία ανάκτησης. Ο νέος κωδικός αποστέλλεται μόνο στο Supabase Auth.","Έλεγχος συνδέσμου ανάκτησης…","Νέος κωδικός","Επιβεβαίωση νέου κωδικού","Χρησιμοποίησε τουλάχιστον 8 χαρακτήρες.","Αποθήκευση νέου κωδικού","Επιστροφή στο WarBoost","Ο σύνδεσμος έληξε. Ζήτησε νέο από το WarBoost.","Ο κωδικός δεν πληροί τις απαιτήσεις ασφαλείας.","Ο σύνδεσμος είναι άκυρος ή έχει ήδη χρησιμοποιηθεί.","Χρησιμοποίησε τουλάχιστον 8 χαρακτήρες.","Οι κωδικοί δεν ταιριάζουν.","Αποθήκευση…","Ο κωδικός ενημερώθηκε. Μπορείς να συνδεθείς με τον νέο κωδικό."],
  cs:["Zapomenuté heslo?","Zadej e-mail WarBoost.","Pokud účet pro tento e-mail existuje, byl odeslán odkaz pro reset.","Obnovení účtu","Zvol nové heslo","Odkaz v e-mailu otevře dočasnou relaci pro obnovení. Nové heslo se odešle pouze do Supabase Auth.","Kontrola odkazu pro obnovení…","Nové heslo","Potvrdit nové heslo","Použij alespoň 8 znaků.","Uložit nové heslo","Zpět do WarBoost","Odkaz vypršel. Vyžádej si nový ve WarBoost.","Heslo nesplňuje bezpečnostní požadavky.","Odkaz je neplatný nebo už byl použit.","Použij alespoň 8 znaků.","Hesla se neshodují.","Ukládání…","Heslo bylo aktualizováno. Nyní se můžeš přihlásit novým heslem."],
  sv:["Glömt lösenordet?","Ange din WarBoost-e-postadress.","Om ett konto finns för e-postadressen har en återställningslänk skickats.","Kontoåterställning","Välj ett nytt lösenord","Länken i e-postmeddelandet öppnar en tillfällig återställningssession. Det nya lösenordet skickas endast till Supabase Auth.","Kontrollerar återställningslänken…","Nytt lösenord","Bekräfta nytt lösenord","Använd minst 8 tecken.","Spara nytt lösenord","Tillbaka till WarBoost","Länken har gått ut. Begär en ny från WarBoost.","Lösenordet uppfyller inte säkerhetskraven.","Länken är ogiltig eller har redan använts.","Använd minst 8 tecken.","Lösenorden matchar inte.","Sparar…","Lösenordet har uppdaterats. Du kan nu logga in med det nya lösenordet."]
};
for(const [code,labels] of Object.entries(V2525_AUTH_LABELS)){
  const targets=code==="en"?[EN,EN_GB,EN_US]:[packs[code]].filter(Boolean);
  targets.forEach(target=>Object.assign(target,{
    forgot_password:labels[0],password_reset_enter_email:labels[1],password_reset_sent:labels[2],
    password_recovery:labels[3],choose_new_password:labels[4],password_recovery_intro:labels[5],
    checking_recovery_link:labels[6],new_password:labels[7],confirm_new_password:labels[8],
    password_minimum:labels[9],save_new_password:labels[10],back_to_warboost:labels[11],
    recovery_link_expired:labels[12],password_too_weak:labels[13],recovery_link_invalid:labels[14],
    password_too_short:labels[15],passwords_do_not_match:labels[16],saving:labels[17],
    password_updated_success:labels[18]
  }));
}
